import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import Button from 'flarum/common/components/Button';
import LinkButton from 'flarum/common/components/LinkButton';
import Notification from 'flarum/forum/components/Notification';
import UserControls from 'flarum/forum/utils/UserControls';
import username from 'flarum/common/helpers/username';

/*
 * forum.js is loaded on every page, so it only wires things up: the routes,
 * the sidebar link, "Write a letter" on profiles, the setting and the two
 * notifications. The post office and the writing desk are chunks fetched
 * when someone opens them.
 */

const t = (key, params = {}) => app.translator.trans(`ernestdefoe-slow-mail.forum.${key}`, params);
class ArrivedNotification extends Notification {
  icon() {
    return 'fas fa-envelope';
  }
  href() {
    return app.route('slow-mail.letter', {
      id: this.attrs.notification.content()?.letter
    });
  }
  content() {
    return t('notification.arrived', {
      username: username(this.attrs.notification.fromUser())
    });
  }
  excerpt() {
    return null;
  }
}
class DeliveredNotification extends Notification {
  icon() {
    return 'fas fa-envelope-circle-check';
  }
  href() {
    return app.route('slow-mail.letter', {
      id: this.attrs.notification.content()?.letter
    });
  }
  content() {
    return t('notification.delivered', {
      username: username(this.attrs.notification.fromUser())
    });
  }
  excerpt() {
    return null;
  }
}
class ReportedNotification extends Notification {
  icon() {
    return 'fas fa-flag';
  }
  href() {
    return app.route('slow-mail.reports');
  }
  content() {
    return t('notification.reported', {
      username: username(this.attrs.notification.fromUser())
    });
  }
  excerpt() {
    return null;
  }
}
app.initializers.add('ernestdefoe/slow-mail', () => {
  const page = () => import(/* webpackChunkName: 'forum/components/SlowMailPage', webpackMode: 'lazy-once' */ './components/SlowMailPage').then(async module => (await module.loadCore(), module));
  app.routes['slow-mail'] = {
    path: '/slow-mail',
    component: page
  };
  app.routes['slow-mail.outbox'] = {
    path: '/slow-mail/outbox',
    component: page
  };
  app.routes['slow-mail.pals'] = {
    path: '/slow-mail/pals',
    component: page
  };
  app.routes['slow-mail.pal'] = {
    path: '/slow-mail/pals/:id',
    component: page
  };
  app.routes['slow-mail.letter'] = {
    path: '/slow-mail/letters/:id',
    component: page
  };
  app.routes['slow-mail.reports'] = {
    path: '/slow-mail/reports',
    component: page
  };
  app.notificationComponents.slowMailArrived = ArrivedNotification;
  app.notificationComponents.slowMailDelivered = DeliveredNotification;
  app.notificationComponents.slowMailReported = ReportedNotification;

  // String form: IndexSidebar lives in a lazy chunk, and extending an imported copy patches one core never renders.
  extend('flarum/forum/components/IndexSidebar', 'navItems', function (items) {
    if (!app.session.user || !app.forum.attribute('slowMailCanSend') || !app.forum.attribute('slowMailNav')) return;
    // Active on every Slow Mail page (outbox, a letter…), so phones' header names it there too.
    const href = app.route('slow-mail');
    const active = window.location.pathname === href || window.location.pathname.startsWith(href + '/');
    items.add('slow-mail', LinkButton.component({
      href,
      icon: 'fas fa-envelope',
      active
    }, t('nav')), 77);
  });
  extend(UserControls, 'userControls', function (items, user) {
    const me = app.session.user;
    if (!me || user === me || !app.forum.attribute('slowMailCanSend')) return;
    items.add('slowMailWrite', m(Button, {
      icon: "fas fa-pen-nib",
      onclick: () => app.modal.show(() => import(/* webpackChunkName: 'forum/components/WriteModal', webpackMode: 'lazy-once' */ './components/WriteModal'), {
        to: {
          id: Number(user.id()),
          slug: user.slug(),
          displayName: user.displayName(),
          avatarUrl: user.avatarUrl()
        }
      })
    }, t('controls.write')), 95);
  });

  // "Who can send me letters", beside the other privacy choices (the settings page is a chunk: named by path).
  extend('flarum/forum/components/SettingsPage', 'privacyItems', function (items) {
    const user = app.session.user;
    if (!user || !app.forum.attribute('slowMailCanSend')) return;
    const current = user.preferences()?.slowMailAccept || 'everyone';
    items.add('slowMailAccept', m("div", {
      className: "Form-group"
    }, m("label", {
      for: "SlowMail-accept"
    }, t('settings.accept')), m("select", {
      id: "SlowMail-accept",
      className: "FormControl",
      value: current,
      onchange: e => user.savePreferences({
        slowMailAccept: e.target.value
      })
    }, m("option", {
      value: "everyone"
    }, t('settings.accept_everyone')), m("option", {
      value: "pals"
    }, t('settings.accept_pals')), m("option", {
      value: "nobody"
    }, t('settings.accept_nobody'))), m("p", {
      className: "helpText"
    }, t('settings.accept_help'))), -20);
  });
  extend('flarum/forum/components/NotificationGrid', 'notificationTypes', function (items) {
    items.add('slowMailArrived', {
      name: 'slowMailArrived',
      icon: 'fas fa-envelope',
      label: t('settings.notify_arrived')
    });
    items.add('slowMailDelivered', {
      name: 'slowMailDelivered',
      icon: 'fas fa-envelope-circle-check',
      label: t('settings.notify_delivered')
    });
    if (app.forum.attribute('slowMailCanModerate')) items.add('slowMailReported', {
      name: 'slowMailReported',
      icon: 'fas fa-flag',
      label: t('settings.notify_reported')
    });
  });
});flarum.reg.addChunkModule('ernestdefoe-slow-mail:forum/components/SlowMailPage', '563', 'ernestdefoe-slow-mail', 'forum/components/SlowMailPage');
flarum.reg.addChunkModule('ernestdefoe-slow-mail:forum/components/WriteModal', '742', 'ernestdefoe-slow-mail', 'forum/components/WriteModal');
flarum.reg.addChunkModule('ernestdefoe-slow-mail:forum/components/SlowMailPage', '563', 'ernestdefoe-slow-mail', 'forum/api');
flarum.reg.addChunkModule('ernestdefoe-slow-mail:forum/components/SlowMailPage', '563', 'ernestdefoe-slow-mail', 'forum/art');
flarum.reg.addChunkModule('ernestdefoe-slow-mail:forum/components/SlowMailPage', '563', 'ernestdefoe-slow-mail', 'forum/components/Envelopes');
flarum.reg.addChunkModule('ernestdefoe-slow-mail:forum/components/SlowMailPage', '563', 'ernestdefoe-slow-mail', 'forum/components/LetterView');